<body>
    <div class="header">
        <h1>Prayer Candle Game</h1>
        <p>Light candles with your prayers</p>
    </div>

    <div class="prayer-area" id="prayerArea"></div>

    <div class="prayer-counter">
        Candles lit: <span id="counter">0</span>
    </div>

    <div class="message" id="message">
        May your prayers bring you peace and comfort.
    </div>

    <button class="reset-btn" id="resetBtn">Reset Candles</button>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const prayerArea = document.getElementById('prayerArea');
            const counter = document.getElementById('counter');
            const message = document.getElementById('message');
            const resetBtn = document.getElementById('resetBtn');

            let litCount = 0;
            const totalCandles = 12;

            // Create candles
            for (let i = 0; i < totalCandles; i++) {
                const candle = document.createElement('div');
                candle.className = 'candle';
                candle.innerHTML = `
                    <div class="flame"></div>
                    <div class="wick"></div>
                    <div class="candle-body"></div>
                `;

                candle.addEventListener('click', function() {
                    if (!candle.classList.contains('lit')) {
                        candle.classList.add('lit');
                        litCount++;
                        counter.textContent = litCount;

                        if (litCount === totalCandles) {
                            message.style.display = 'block';
                        }
                    }
                });

                prayerArea.appendChild(candle);
            }

            // Reset button
            resetBtn.addEventListener('click', function() {
                const candles = document.querySelectorAll('.candle');
                candles.forEach(candle => {
                    candle.classList.remove('lit');
                });
                litCount = 0;
                counter.textContent = litCount;
                message.style.display = 'none';
            });
        });
    </script>
</body>
